    "corePrinciple": "4포지션 이상의 고음역대 진입 시, 넥과 악기 바디의 물리적 간섭을 피해 손바닥 기저부를 악기 어깨(Ribs)에 자연스럽게 밀착시키고 왼쪽 팔꿈치 조향을 극대화하여 좁아진 공간 내에서 손의 자유로운 진동 프레임을 유지하는 기술.",
    "before": "하이 포지션 진입은 손가락만 억지로 뻗어 올라가는 것이 아니라, 팔 전체의 프레임이 바이올린을 부드럽게 타고 올라가는 자연스러운 과정임을 상기합니다.\n엄지손가락이 넥의 곡선을 따라 밑면으로 부드럽게 파고들어, 손바닥과 손가락이 움직일 수 있는 충분한 공간을 열어주는 궤적을 시각화합니다.\n하이 포지션에서도 1번과 4번 손가락의 옥타브 프레임 구조적 밸런스는 동일하며, 단지 지판의 특성상 음정 간격이 시각적/물리적으로 좁아질 뿐임을 인지합니다.\n왼쪽 팔꿈치가 몸통 쪽(오른쪽)으로 충분히 깊숙하게 들어와 손가락 패드가 E현, A현에 안정적인 수직 각도로 닿는 감각을 예행연습합니다.\n손바닥 기저부(손목 안쪽)가 바이올린의 어깨 둥근 부분에 부드럽게 닿아 하이 포지션에서의 새로운 닻(Anchor) 역할을 하는 것을 상상합니다.\n쉬프팅 과정에서 엄지손가락이 결코 브레이크처럼 작용하여 흐름을 끊지 않도록, 엄지 근육을 속으로 마사지하며 텐션을 제로(0)로 세팅합니다.",
