    "before": "연주 전 바이올린의 네 개방현이 낼 수 있는 고유의 배음과 공명음을 머릿속으로 미리 선명하게 상상합니다.\n튜너의 시각적 바늘에 의존하려는 마음을 버리고, 내 귀와 악기의 울림만이 유일한 나침반이라는 마인드셋을 갖습니다.\n음정을 짚기 전, 악기 전체가 어떻게 떨릴지 그 진동의 감각을 미리 피부로 기대하며 예행연습을 합니다.\n왼손가락을 망치처럼 내리찍는 대신, 현 위에 부드럽게 얹어 악기의 울림을 막지 않겠다는 이완 상태를 만듭니다.\n'맞다/틀리다'라는 이분법적 사고를 버리고, 악기가 가장 맑게 노래하는 '스윗 스팟(Sweet Spot)'을 찾겠다는 탐험가의 태도를 가집니다.\n공명음이 발생할 때 방 전체의 공기가 함께 울린다는 공감각적인 이미지를 떠올리며 연주 모드에 진입합니다.",
