    "before": "더블 스탑은 한 번에 두 가지 문제를 해결하는 것이 아니라, 두 개의 독립적인 음이 완벽히 조화를 이루는 과정임을 상기합니다.\n두 손가락을 모두 지판에 얹되, 활은 마치 레이저 포인터처럼 오직 한 줄씩만 겨냥해 그을 것이라고 시각화합니다.\n음정이 빗나갔을 때 본능적으로 지판을 스멀스멀 비벼서(Sliding) 맞추려는 유혹을 철저히 차단하겠다고 다짐합니다.\n손가락을 들어 올릴 때 이전의 틀린 모양을 유지한 채 떼어내고, 공중에서 궤적을 수정한 뒤 깨끗하게 다시 낙하하는 이미지를 그립니다.\n아래 음이 뿌리이고 윗 음이 가지라는 수직적 구조를 머릿속으로 그리며 아래 음의 안정성을 먼저 믿습니다.\n수정된 완벽한 프레임을 뇌가 근육의 거리감으로 사진 찍듯 저장(Capture)하는 찰나의 정적을 즐길 준비를 합니다.",
