    "before": "바이올린이 5도로 조율되어 있다는 사실을 인지하고, 5도 이중음이 모든 스케일과 핸드 프레임의 가장 든든한 뼈대임을 마음에 새깁니다.\n손가락을 뾰족하게 세워 두 현 사이를 아슬아슬하게 쪼개 누르는 것이 아니라, 마디를 부드럽게 펴 넓은 지문(패드)이 두 현을 포근하게 덮는 이미지를 시각화합니다.\nG현과 D현을 짚을 때는 팔꿈치가 몸 안쪽으로, A현과 E현을 짚을 때는 바깥쪽으로 미세하게 움직이는 조향(Steering) 궤적을 예행 연습합니다.\n손가락이나 손목을 인위적으로 비틀어 억지로 5도를 짚는 것이 아니라, 팔 전체의 체중이 지판 위로 자연스럽게 투하된다는 마인드셋을 갖습니다.\n5도 연주 시 손가락이 두 줄에 균일하게 밀착되어, 어느 한쪽 줄의 소리가 비거나 흐려지지 않는 완벽한 밸런스를 예감합니다.\n5도 위에 옥타브나 다른 손가락을 얹을 때도 이 베이스 앵커가 흔들리지 않는 견고한 반석이 된다고 상상합니다.",
