    "name": "6도 연주 시 윗음 중심 조율 (Top-Note Centric Tuning in Sixths)",
    "corePrinciple": "6도 이중음 연주 시, 화성 구조상 주선율 역할을 하는 '윗음(높은 음)'을 스케일 도수에 맞게 선명하게 조율하고 아랫음은 이에 맞춰 공명하도록 유도하는 윗음 주도형 수직-수평 통합 튜닝 역학.",
    "before": "6도는 3도만큼 자주 나오지는 않지만, 등장할 때마다 윗음이 프레이즈의 멜로디 라인을 명확하게 리드해야 함을 음악적으로 인지합니다.\n수직적인 화음의 느낌보다, 윗음이 스케일의 도수를 따라 수평적으로 나아가는 방향성을 먼저 머릿속으로 노래합니다.\n이끎음 성격을 가진 윗음(예: G로 향하는 F#)을 짚을 때 기분 좋게 좁혀(Sharp) 잡는 손가락의 탄력을 시각화합니다.\n아랫음은 윗음의 선율을 방해하지 않고 묵묵히 서포트하며, 악기 전체의 둥근 공명을 이끌어내는 '따뜻한 그림자'라고 상상합니다.\n손가락이 서로 다른 줄에 교차되어 꼬이기 쉬운 6도의 형태를 극복하기 위해, 팔꿈치와 손목의 유연한 조향을 예행 연습합니다.\n소리가 너무 울렁거린다면(Beaty) 내 귀와 취향에 맞춰 윗음의 날카로움을 살짝 타협하여 완벽한 공명점을 찾는 유연한 마인드셋을 갖습니다.",
    "during": [
      "[모양 확인] 6도를 짚기 위해 손가락이 서로 엇갈릴 때, 높은 음을 짚는 손가락이 찌그러지지 않고 단단하고 둥근 아치를 리드하고 있는지 체크",
      "[모양 확인] 활이 두 현을 동시에 그을 때, 윗음에 선율이 실릴 수 있도록 활의 앵글이 완벽하게 50:50이거나 미세하게 윗줄에 배분되는지 확인",
      "[모양 확인] 6도 이중음을 짚은 상태에서도 손바닥 전체의 프레임이 안으로 과하게 비틀리거나 넥을 꽉 움켜쥐는 경직이 없는지 점검",
      "[느낌 확인] 위쪽 음(탑 노트)이 프레이즈의 멜로디를 이끌어가는 확실한 방향성(예: 목적음을 향한 긴장감)이 손끝의 텐션으로 느껴지는지 체크",
      "[느낌 확인] 아랫음은 윗음의 튜닝에 철저히 종속되어, 화음이 울릴 때 부딪히는 쇳소리 없이 따뜻하게 섞여 들어가는 포근함이 감지되는지 확인",
      "[느낌 확인] 활의 압력을 억지로 주입하지 않아도 두 음이 조화를 이루며 악기 바디 전체가 기분 좋게 공명(Ringing)하는지 점검",
      "[소리 확인] 6도 화음을 연주할 때, 멜로디의 중심이 되는 윗음이 스케일 도수에 맞게 선명하게 튜닝되어 곡의 화성적 색채와 방향성을 명확히 이끌어주는가?",
      "[소리 확인] 손목을 무리하게 꺾어 발생하는 경직된 마찰음 없이, 코어 밸런스가 유지된 상태에서 두 음이 부드럽고 평온하게 융합되는 소리가 들리는가?",
      "[소리 확인] 소리를 키우려다 활을 짓눌러 발생하는 거친 쇳소리 없이, 윗음의 맑은 멜로디가 투명하게 살아있고 아랫음이 그 밑을 풍성하게 받쳐주는가?"
    ],
    "after": [
      {
        "symptom": "6도 이중음은 소리가 나는데 멜로디 라인이 지루하게 들리고 곡의 생동감이 죽어버림",
        "cause": "윗음(탑 노트)을 스케일 도수나 선율의 긴장도에 맞게 튜닝하지 않고 기계적인 평균율 수직 화음에만 맞춰 멜로디의 방향성을 상실함",
        "prescription": "아랫음을 제외하고 윗음만 단선율로 먼저 연주하며 음악적 방향(예: 이끎음의 당김)을 귀에 각인시킨 뒤, 그 피치를 유지한 채 아랫음을 살짝 얹어 튜닝함"
      },
      {
        "symptom": "6도 연속 패시지를 연주할 때 손가락이 자꾸 꼬이고 손등 외측 근육에 빠른 경련이 옴",
        "cause": "서로 다른 줄을 짚는 6도 특유의 교차 프레임을 손가락 근력만으로 찢어 잡으려 하며, 팔꿈치의 조향을 통한 각도 보상이 부재함",
        "prescription": "손가락을 뻗기 전 왼쪽 팔꿈치를 안팎으로 가볍게 스윙하여 손바닥 각도를 재조정하고, 기저 관절(너클) 부위의 V자 공간을 인위적으로 열어 긴장을 해소함"
      },
      {
        "symptom": "6도를 그을 때 부드러운 화음 대신 날카롭고 긁히는 듯한 불협화음 소음이 거슬림",
        "cause": "윗음을 너무 날카롭게(Sharp) 잡아 아랫음과의 순정률 비율이 붕괴되어 과도한 맥놀이(Beating)가 발생했거나 활 압력이 짓눌림",
        "prescription": "활의 압력을 하모닉스 수준으로 대폭 줄이고 윗음의 피치를 아주 미세하게 낮춰보며 소리가 탁 트이는(Blooming) 타협점의 공명 지점을 귀로 찾음"
      }
    ],
