    "corePrinciple": "3도 화음 연주 시 장3도와 단3도의 물리적 손가락 간격 차이를 인지하고, 손의 반시계 방향 확장을 통해 손목을 이완하며 두 주파수가 완벽히 섞이는 수직적 순정률 비율을 찾아 타르티니 톤(결합음)을 끌어내는 조율 기술.",
    "before": "장3도와 단3도의 미세한 간격 차이와 그에 따른 손가락의 둥근 아치를 머릿속으로 먼저 선명하게 시각화합니다.\n두 음이 완벽하게 섞일 때 나타나는 타르티니 톤(결합음)을 내면의 귀로 명확히 듣겠다는 확고한 청각적 목표를 세웁니다.\n손의 반시계 방향 확장을 돕기 위해 손목을 완전히 부드럽고 이완된 상태로 리셋합니다.\n피아노의 평균율처럼 고정된 폭으로 짚는 것이 아니라, 귀의 판단에 따라 미세하게 간격을 좁히거나 넓힐 유연성을 예감합니다.\n두 손가락이 지판을 억지로 짓누르는 것이 아니라, 현 위에 가볍게 얹혀 최적의 공명점(Sweet spot)을 스스로 찾아간다고 상상합니다.\n오른손 활은 균등한 무게 배분을 위해 두 줄을 50:50으로 마찰할 평형 궤적을 허공에서 미리 그립니다.",
