    "before": "10도는 1번과 4번 손가락이 감당해야 할 가장 넓은 익스텐션이므로, 손에 인위적인 긴장을 미리 주입하지 않도록 심리적 이완을 먼저 확실히 수행합니다.\n아래 음에서 위로 억지로 뻗어 올라가는 벅찬 등반의 이미지를 버리고, 위에서 아래로 편안하게 내려다보는 안정적인 구도를 시각화합니다.\n5포지션 등 상위 음역대에 손 전체를 먼저 통째로 위치시켜 4번 손가락을 중심축(Anchor)으로 삼는 역방향 셋업 방식을 머릿속으로 시뮬레이션합니다.\n4번을 짚은 후 1번을 향해 뒤로 뻗을 때, 왼쪽 손목과 손바닥 기저부가 부드럽게 열리며 물리적인 길이를 완벽히 보상해 주는 과정을 예행 연습합니다.\n손가락 사이를 단순히 근력으로 찢는 것이 아니라, 어깨 관절과 팔꿈치의 치밀한 조향 각도가 뒷받침되어야 도달할 수 있는 프레임임을 상기합니다.\n10도가 완벽히 조율되었을 때 얻어지는 풍성하고 빛나는 두 주파수의 화성적 결합을 내면의 귀로 강렬하게 기대하며 세팅을 마칩니다.",
