      "[느낌 확인] 높은 E현 등에서 10도를 연주할 때 줄을 지판 바닥 나무 끝까지 짓누르는 과도한 압력 없이, 소리가 명확하게 날 정도의 최소 압력(MVP)만 유지되는가",
