    "sourceHeading": "## 1.3 스케일 & 아르페지오",
    "sourceLine": 510,
    "name": "아르페지오",
    "corePrinciple": "음표가 생략된 스케일의 확장 형태로, 방대한 지판에서의 넓은 도약과 잦은 현 교차 속에서도 손의 뼈대(Hand Frame)를 견고하게 유지하며 화성의 울림을 수평적으로 잇는 복합 제어 기술이다.",
    "before": "아르페지오를 단순히 어려운 도약 쉬프팅의 연속이 아니라, 완벽한 화성 구조를 지닌 아름다운 '생략형 스케일'로 인식합니다.\n연주 전 1도, 3도, 5도 기둥 화음의 구조를 시각화하며, 이동해야 할 포지션 블록들의 지도를 머릿속에 명확히 그립니다.\n상행 시 1번과 4번 손가락 사이의 간격이 멀어질 것을 미리 계산하며, 쉬프팅 도착 전 공중에서부터 손가락 사이의 공간을 넓힐(Expansion) 준비를 합니다.\n빈번한 현 교차를 유연하게 소화하기 위해 활을 쥔 오른팔이 각 현의 중간 지점을 둥근 아치 형태로 미끄러지듯 통과할 것을 상상합니다.\n하이 포지션으로 진입할 때 팔꿈치가 조향을 적극적으로 리드하여, 넓은 간격을 도약하더라도 손가락 끝이 정확한 각도로 떨어지도록 세팅합니다.\n개방현과 공명하는 주요 화음의 진동을 내면의 귀에 미리 튜닝하여, 어긋남 없는 수직적 화음과 수평적 멜로디 라인을 모두 잡겠다는 목표를 세웁니다.",
    "during": [
      "[모양 확인] 상행 도약하여 하이 포지션에 안착할 때, 1번과 4번 손가락 사이가 좁아지지 않고 허공에서 미리 넓게 확장(Expansion)되어 대기하는지 체크한다.",
      "[모양 확인] 현 교차가 끊임없이 발생할 때 오른쪽 팔꿈치가 급격하게 위아래로 들썩이지 않고, 물 흐르듯 둥글고 부드러운 곡선(엘리베이터 움직임)을 그리는지 점검한다.",
      "[모양 확인] 쉬프팅으로 고음역에 도달하기 전, 왼팔 팔꿈치가 E현 방향으로 깊숙이 스윙(Swing)하며 손의 넓은 도약을 역학적으로 돕고 있는지 관찰한다.",
      "[느낌 확인] 넓은 음정 간격을 건너뛸 때 손가락만 억지로 찢어 텐션을 유발하지 않고, 손목과 팔 전체가 위치를 보조해 주어 목표 지점에 편안하게 떨어지는 감각을 느낀다.",
      "[느낌 확인] 장 3도와 단 3도 간격의 변화에 따라 손가락 사이의 거리가 미세하게 조절되는 것을 느끼고, 튜닝이 완벽할 때 타르티니 톤(결합음)이 악기를 울리는 진동을 감지한다.",
      "[느낌 확인] 활이 여러 줄을 신속하게 넘어갈 때 오른손 손가락 관절들이 유연한 서스펜션 역할을 하여, 덜컹거리는 저항 없이 매끄러운 밀착감을 확보하는지 체감한다.",
      "[소리 확인] 현을 넘어갈 때마다 덜컹거리거나 뚝뚝 끊어지는 충격음 없이, 오른팔의 둥글고 유연한 궤적을 통해 하나의 선으로 흐르는 유려한 레가토 선율이 유지되는가?",
      "[소리 확인] 최고음에서 하행으로 도약할 때 불안한 마찰음 없이, 1번 손가락의 명확한 가이드 궤적을 통해 정확한 목적지에 도달하는 깨끗하고 단호한 타격음이 나는가?",
      "[소리 확인] 1번과 4번 손가락의 옥타브 간격을 짚을 때 관절이 꺾이며 활이 짓눌리는 파열음 대신, 안정된 프레임을 바탕으로 각 음표가 순수하게 열린(Open) 배음으로 울리는가?"
    ],
