      "[느낌 확인] 왼손이 극한의 속도로 타격하고 튕겨 오르는 동안, 활을 쥐고 있는 오른손은 전혀 동요하지 않고 물 흐르듯 유연한 상태를 유지하는지 점검한다.",
      "[소리 확인] 초고속 템포에서 손가락 끝으로 지판을 억지로 내리찍는 둔탁한 타격음 대신, 손가락 패드의 탄력을 활용한 명료하고 둥근(Round) 어택 소리가 나는가?",
