    "name": "더블스탑 스케일",
    "corePrinciple": "두 개의 음을 동시에 연주하며 수평적 선율 이동과 수직적 화음(배음)의 튜닝을 완벽히 일치시키고, 왼손 핸드 프레임의 구조적 긴장감을 관리하는 다중 통제 기술이다.",
    "before": "두 음이 완벽하게 맞았을 때 발생하는 타르티니 톤(제3의 결합음)과 배음의 풍성한 울림을 상상하며 청각적 기준을 극대화합니다.\n왼손의 긴장도를 점검하며, 두 손가락을 강하게 누르고 있어도 관절과 손목이 부드러운 상태를 유지할 수 있도록 마인드 컨트롤을 합니다.\n각 더블스탑이 장음정인지 단음정인지 미리 분석하여 손가락의 넓고 좁은 형태를 논리적으로 시각화합니다.\n오른팔의 활이 두 현에 동일한 무게와 압력을 전달하여 밸런스 있는 소리를 낼 수 있도록 활털의 밀착감을 상상합니다.\n쉬프팅을 할 때 두 손가락이 개별적으로 움직이는 것이 아니라 하나의 완전한 블록(Block)으로 이동한다는 그림을 그립니다.\n불협화음이나 잦은 수정으로 인해 귀와 몸이 피로해지지 않도록, 천천히 인내심을 갖고 진행하겠다는 명확한 목표를 세웁니다.",
