      "[느낌 확인] 포르테(f)로 연주할 때 어깨의 억지스러운 텐션 대신, 등에서부터 전달되는 자연스러운 팔의 무게가 현에 묵직하게 매달리는 느낌을 감지한다.",
      "[느낌 확인] 디미누엔도를 연주할 때 활이 허공으로 떠서 마찰력을 잃는 것이 아니라, 가벼워지면서도 현을 끈적하게 물고 있는 저항감을 손끝으로 느낀다.",
      "[느낌 확인] 크레셴도를 위해 활의 속도를 급격히 높일 때, 왼손가락 역시 팽창하는 에너지를 감당하기 위해 더 단호하고 날카로운 타격감으로 지판을 짚는지 체크한다.",
      "[소리 확인] 다이내믹을 키울 때 활 속도나 접촉점의 이동 없이 수직적인 악력만으로 억지로 내리눌러 배음이 죽고 거칠게 찌그러지는(Crushed) 파열음이 나지 않는가?",
      "[소리 확인] 피아노(p) 다이내믹을 연주할 때 소리가 커질까 봐 두려워 활의 마찰력을 완전히 풀어버려서 나는 흐릿하고 겉도는 얕은 소리(Glassy sound)가 완전히 사라졌는가?",
