    "sourceLine": 628,
    "name": "데타셰와 슬러의 유연한 전환 (Flexible Détaché & Slur Mix)",
    "corePrinciple": "한 음표에 한 활을 쓰는 데타셰의 명료한 수평적 마찰력과, 여러 음표를 하나의 매끄러운 궤적으로 잇는 슬러를 융합하여 오른손의 활 컨트롤과 왼손의 타격 독립성을 완벽히 분리 및 동기화하는 기술이다.",
    "before": "스케일을 기계적인 슬러로만 켜거나 데타셰로만 켜는 단순한 편식에서 벗어나, 레퍼토리에서 요구하는 어떠한 복합 보잉 지시에도 흔들림 없이 반응할 수 있는 몸을 준비합니다.\n슬러를 연주할 때는 오른팔이 물 흐르듯 유연한 하나의 거대한 궤적(Arc)을 그리며, 왼손가락은 그 선 위에서 독립적인 피아노 건반처럼 명료하고 고르게 떨어질 것을 시각화합니다.\n데타셰를 연주할 때는 각 음표가 뚝뚝 끊기는 것이 아니라 현과의 끈적하게 밀착된 상태를 유지하며, 활의 방향이 바뀌는 찰나의 충격을 완벽히 흡수할 것을 다짐합니다.\n슬러 도중 현을 교차(String crossing)할 때 활이 덜컹거리지 않도록, 오른팔 팔꿈치가 이전 현에서 이미 다음 현의 높이를 예비(Anticipation)하며 부드럽게 유도하는 각도를 세팅합니다.\n왼손의 경쾌한 타격 속도가 오른손의 느릿한 활 속도에 휘둘리지 않고, 철저하게 내면의 메트로놈에 맞춰 완벽한 싱크로율을 이루는 양손의 독립적인 역할을 상상합니다.\n협주곡에서 마주칠 '슬러 2개 + 데타셰 2개' 등 복합적인 활 쓰기 패턴을 미리 대입해 보며 실전에서 발생할 수 있는 활 배분의 오류를 사전에 철저히 차단할 마인드를 갖습니다.",
