    "corePrinciple": "1번 손가락과 4번 손가락 사이의 절대적인 핸드 프레임(Hand Frame)을 견고하게 유지한 채 지판을 상하로 활주하며, 두 음의 완벽한 수직적 튜닝을 통해 공명을 극대화하는 뼈대 확립 기술이다.",
    "before": "옥타브는 왼손 핸드 프레임의 절대적인 기준을 세우는 가장 중요한 기둥임을 인식하고, 1번과 4번 손가락의 뼈대를 굳건히 하겠다고 다짐합니다.\n쉬프팅 시 1번과 4번 손가락이 개별적으로 움직이는 대신, 두 손가락이 금속 막대로 연결된 것처럼 굳건한 하나의 블록(Block)으로 이동하는 모습을 시각화합니다.\n하이 포지션으로 상행할수록 1번과 4번 사이의 물리적 거리가 좁아짐을 인지하고, 이동 궤적을 따라 손가락 간격이 부드럽게 수축하는 감각을 상상합니다.\n완벽한 옥타브가 맞았을 때, 맥놀이(울렁거림)가 사라지고 하나의 꽉 찬 소리로 악기 바디가 폭발적으로 공명하는 그 순간을 귀에 세팅합니다.\n새끼손가락(4번)이 무너지지 않도록 둥글고 단단한 관절 형태를 유지하되, 엄지손가락과 손목에는 절대 힘을 주지 않고 유연하게 이완시킵니다.\n두 현에 활을 댈 때, 어느 한 현으로 무게가 쏠리지 않고 평행하고 고른 마찰력을 발생시켜 완벽한 음향 밸런스를 만들 준비를 합니다.",
