      "[모양 확인] 1-3번에서 2-4번으로 쌍이 교체될 때, 손목과 손 전체의 각도가 과도하게 비틀리지 않고 일정한 틀을 유지하며 자연스럽게 교대되는지 거울로 점검한다.",
      "[모양 확인] 엄지손가락이 넥을 꽉 움켜쥐지 않고 넥 아래쪽에서 유연하게 지지하며, 손가락들이 위로 뻗어나갈 수 있도록 손바닥을 둥글게 열어주고 있는지 관찰한다.",
