      "[느낌 확인] 손가락 쌍이 교체될 때 이전 손가락의 압력이 즉각적으로 풀리며, 새로운 손가락 쌍으로 무게 중심이 물 흐르듯 이동하는 릴레이 감각을 손끝으로 확인한다.",
