    "name": "가이드 음 쉬프팅 (Guide Finger Shift / Classical Shift)",
    "corePrinciple": "현재 연주 중인 '옛 손가락'을 목표 포지션의 중간 기착지(가이드 음)까지 미끄러트려 손의 형태(프레임)를 완성한 뒤, '새 손가락'을 떨어뜨려 정확도를 높이는 이동 기술.",
    "before": "악보를 보며 어떤 손가락이 미끄러지는 가이드 손가락이고 어떤 손가락이 새롭게 떨어질 손가락인지 분석합니다.\n가이드 손가락이 도달해야 할 중간 기착지(가이드 음)의 정확한 피치를 마음속으로 명확히 소리 내어 듣습니다.\n빠른 쉬프트 패시지라도 마음의 여유를 갖고 활이 바뀌는 타이밍과 손이 이동하는 시점을 정교하게 계획합니다.\n손가락만 억지로 뻗어서 목표 음을 짚으려는 본능을 버리고, 손 전체가 해당 포지션으로 이동할 준비를 마칩니다.\n머릿속으로 '미끄러짐(Slide) - 도착(Arrive) - 떨어짐(Drop)'이라는 3단계 안무를 슬로우 모션으로 시뮬레이션합니다.\n긴장으로 인해 호흡이 멈추지 않도록 깊게 숨을 들이마시고 내쉬는 템포에 이동의 순간을 자연스럽게 맞춥니다.",
