    "corePrinciple": "목표 포지션에 도달하는 정확한 찰나에 '새 손가락'이 슬라이딩하던 '옛 손가락'의 자리를 밀어내듯(Substitution) 교차하여, 지저분한 슬라이드 소리 없이 완벽한 레가토를 만드는 고급 기술.",
    "before": "상행이나 하행 중 새 손가락이 옛 손가락을 정확히 어느 타이밍에 밀어낼 것인지 머릿속으로 철저히 계산합니다.\n템포가 빠를 경우, 교환 시 손가락들이 좁게 뭉치는 '압축된 프레임'을 견딜 수 있도록 손목과 관절을 이완시킵니다.\n쉬프트를 두려워하는 마음을 버리고, 제자리에 있는 음을 편안하게 짚는 것처럼 자연스러운 움직임을 상상합니다.\n활의 어떤 부분(old bow vs new bow)에서 손가락의 교체가 일어날 것인지 명확히 결정하고 시각화합니다.\n손목의 부드러운 반동을 이용해 손가락이 마치 아이스스케이트를 타듯 매끄럽게 교차되는 이미지를 떠올립니다.\n두 손가락이 동시에 공중에 떠서 음이 비는 상황을 피하기 위해, 현과의 끈적한 밀착감을 연주 전 한 번 더 되새깁니다.",
