    "name": "하행 쉬프팅 (Downward Shift)",
    "corePrinciple": "높은 포지션에서 낮은 포지션으로 이동할 때, 손목과 엄지손가락이 미세하게 손을 선행하여 이끌며 새끼손가락의 곡선을 유지해 프레임의 붕괴를 막는 이동 기술.",
    "before": "하행 전, 왼쪽 어깨가 악기가 떨어질까 두려워 위로 솟아있거나 긴장되어 있지 않은지 의식적으로 끌어내리며 체크합니다.\n손목과 엄지손가락이 하행의 '선발대' 역할을 할 수 있도록 넥보드 주변 근육을 유연하고 젤리처럼 풀어줍니다.\n바이올린을 턱으로 강하게 짓누르지 않고 쇄골 위에서 안정적이면서도 자유롭게 지탱되는 느낌을 확인합니다.\n내려가야 할 정확한 거리를 눈과 근육의 기억으로 가늠하며, 손 전체가 중력을 타고 미끄럼틀을 내려가는 느낌을 상상합니다.\n내려오는 과정에서 4번 손가락(새끼손가락)이 쭉 펴지지 않도록 연주자 쪽을 향한 둥근 형태를 미리 유지하도록 세팅합니다.\n연주할 프레이즈의 음악적 호흡에 맞춰 슬라이딩의 속도를 끈적하게 늦출지, 민첩하게 빠르게 할지 머릿속으로 결정합니다.",
