    "before": "아주 높은 포지션의 목표 음을 연주할 때 내 얼굴과 가까워진다는 '아늑한' 이미지를 상상하여 도약의 공포감을 없앱니다.\n도약하기 전 개방현이나 하모닉스를 연습하며 왼팔 전체가 바이올린 넥 위를 부드럽게 활공하는 감각을 일깨웁니다.\n높은 포지션의 도착 지점에서 엄지손가락이 뒤에 남지 않고 바이올린 몸통 아래(ribs) 틈새에 위치할 것을 시각화합니다.\n손가락을 미리 뻗어 짚으려는 근육의 긴장 상태를 버리고, 점프를 위한 팔의 스윙 궤적을 크고 둥글게 설계합니다.\n빠른 속도의 도약을 위해 처음부터 끝까지 중간에 멈춤 없는 한 번의 매끄러운 움직임으로 도달하겠다는 확신을 가집니다.\n활의 속도를 시프트 직전에 맞추어 조절할 계획을 세우며, 양손의 협응 상태를 머릿속으로 완벽히 동기화합니다.",
