      "[느낌 확인] 손목이나 새끼손가락 관절 자체에서 비브라토의 동력을 쥐어짜는 것이 아니라, 팔 전체의 흔들림이 손끝으로 묵직하게 전달되는가?",
      "[느낌 확인] 연주 시 손바닥 안쪽이나 엄지손가락에 과도한 경직이 발생하지 않고, 관절들이 탄력 있는 용수철처럼 유연하게 반응하는가?",
