    "name": "기본 단일 트릴 (Basic Single Trill)",
    "corePrinciple": "트릴은 현을 강하게 때리는 타격 운동이 아니라, 베이스 손가락과 엄지, 검지 측면의 견고한 삼각대 지지를 바탕으로 트릴 손가락을 번개처럼 가볍게 '떼어내는(Lifting)' 이완 및 반사 운동이다.",
    "before": "트릴은 무조건 빨리 움직여야 한다는 강박을 버리고 조절된 왼손의 활동이라는 점을 명심합니다.\n운지하는 손가락 끝, 엄지손가락, 그리고 검지 옆면이 넥을 지지하는 견고한 '삼각대' 구조를 설정합니다.\n엄지손가락으로 넥을 꽉 쥐고 있지 않은지 점검하고, 필요하다면 엄지를 넥 아래로 살짝 옮겨 손을 자유롭게 엽니다.\n트릴을 수행할 손가락이 지판과 수직으로 서기보다는, 푹신한 살(flesh)이 조금 더 닿을 수 있도록 손가락 각도를 약간 눕혀줍니다.\n손가락을 현에서 때리려는 생각 대신, 현에서 튕겨져 오르듯 가볍게 들어 올린다는 이미지를 슬로우 모션으로 시뮬레이션합니다.\n어깨와 목의 긴장을 풀고, 트릴 중에도 기본음의 비브라토 잔여 느낌이 유지될 수 있도록 손목을 유연하게 풀어줍니다.",
    "during": [
      "[모양 확인] 운지하는 베이스 손가락과 엄지, 검지 측면의 삼각 지지대가 흔들림 없이 안정적으로 넥을 받쳐주고 있는가?",
      "[모양 확인] 트릴을 하는 손가락이 관절의 근원(기저 관절)에서부터 부드럽게 움직이며 일정한 높이로 올라갔다 내려오는가?",
      "[모양 확인] 트릴을 하지 않는 나머지 손가락들이 허공에 뻣뻣하게 들려 있거나 경직되어 있지 않고 편안하게 구부러져 있는가?",
      "[느낌 확인] 트릴 손가락을 내리칠 때의 압력보다, 손가락을 현에서 위로 들어 올릴 때(Lifting)의 가벼운 반발력이 더 선명하게 느껴지는가?",
      "[느낌 확인] 베이스가 되는 손가락이 지판을 과도하게 짓누르지 않고, 현을 안정적으로 고정할 수 있는 최소한의 압력(MVP)만 유지하고 있는가?",
      "[느낌 확인] 트릴 속도가 빨라지더라도 손목과 팔뚝에 쥐가 나는 듯한 경직이 없고, 손바닥 전체가 유연하게 열려 있는 느낌이 드는가?",
      "[소리 확인] 트릴을 할 때 손가락을 너무 높이 치켜들었다가 지판을 망치처럼 퍽퍽 내리치는 둔탁한 타격음 대신, 현과 가깝게 밀착된 상태에서 가볍고 명료하게 떨어지는 찰진 발음이 나는가?",
      "[소리 확인] 엄지손가락으로 넥을 꽉 쥐어짜서 전체적인 손의 텐션이 높아진 결과로 나는 짓눌리고 뻣뻣한 소음 없이, 맑고 투명한 배음 진동이 질식되지 않고 여유롭게 지속되는가?",
      "[소리 확인] 손가락의 독립성 없이 팔이나 손목 전체를 경련하듯 떨어 발생시키는 기계적이고 불규칙한 소리 대신, 진주알이 굴러가듯 빠르고 고른(Even) 리듬의 깨끗한 트릴이 들리는가?"
    ],
