    "before": "악보의 16분음표들을 개별적인 낱알로 보지 않고, 2개, 3개 혹은 4개 단위의 의미 있는 덩어리(Chunk)로 시각적으로 묶어냅니다.\n그룹의 첫 음에 도달하는 순간, 나머지 음들은 생각할 겨를도 없이 반사적으로 거의 동시에 지판에 떨어진다는 이미지를 그립니다.\n그룹 내의 손가락 움직임은 아주 가벼운 한 번의 단위 동작으로 묶고, 그룹과 그룹 사이의 대기 시간에는 충분한 휴식을 계획합니다.\n마음속으로 '타-다-다'와 같이 리듬 실러블을 빠르게 부르며, 뇌의 명령 속도가 손가락의 물리적 속도를 앞서도록 동기화합니다.\n빠른 동작 후 정지하는 대기 순간에 다음 그룹의 손가락 배치와 운지 패턴을 미리 머릿속으로 능동적으로 시뮬레이션합니다.\n템포를 올리지 못하는 '느린 습관'의 한계를 부수기 위해, 스스로를 속일 만큼 극한의 빠른 속도로 덩어리를 쏟아내겠다고 다짐합니다.",
