    "corePrinciple": "현의 진동을 브릿지 쪽으로만 유효하게 끊어내기 위해 필요한 절대적인 최소한의 압력(0~10 중 약 4~5 수준)만을 사용하여, 왼손의 긴장을 원천 차단하고 초고속 민첩성을 달성하는 기술.",
    "before": "내 손가락이 낼 수 있는 압력의 0(허공)부터 10(짓누름)까지의 감각을 상상하고, 찾아야 할 완벽한 타협점(최소 유효 압력)을 뇌에 프로그래밍합니다.\n하모닉스를 연주할 때의 가벼운 접촉감(압력 1단계)을 먼저 손끝에 일깨워, 불필요한 힘을 완전히 뺀 상태의 가벼움을 기준점으로 삼습니다.\n현을 '세게 눌러야 크고 좋은 소리가 난다'는 강박을 버리고, 활의 무게와 속도가 소리의 본질임을 확실히 믿겠다고 다짐합니다.\n빠른 스케일이나 패시지를 연주할 때 왼손은 깃털처럼 가볍게 날아다니고, 오른손은 포르테(Forte)로 묵직하게 밀착되는 '양손 분리'를 시뮬레이션합니다.\n손가락 끝에 굳은살이 단단히 박힌 형태를 상상하여, 근육의 억지스러운 텐션 없이 뼈와 굳은살만으로 깔끔하게 지판을 제압할 준비를 합니다.\n힘을 빼는 것과 흐느적거리는 것을 명확히 구분하며, 손가락 형태는 단단하게 유지하되 현을 누르는 하중만을 덜어내는 정교한 영점 조절을 실시합니다.",
