      "[느낌 확인] 매우 크고 강렬한 다이내믹을 연주할 때에도, 왼손의 손목과 전완근은 전혀 피로하지 않고 오히려 가벼운 휴식 상태처럼 느껴지는가?",
      "[소리 확인] 큰 볼륨(f)을 낼 때 왼손으로 지판을 억지로 짓눌러 발생하는 꽉 막힌 쇳소리 대신, 최소한의 압력만으로 악기 전체가 진동하는 풍성하고 열린(Open) 배음이 들리는가?",
