    "before": "세 음표를 수직적인 기둥으로만 둔탁하게 보지 않고, 멜로디 라인이 길게 흘러가는 수평적인 선율선으로 시각화합니다.\n저음현(베이스)과 고음현(탑 노트)이 가지는 장력과 저항이 다르다는 물리적 사실을 인지하고, 그에 맞춘 활의 비대칭적 궤적을 계획합니다.\n저음역은 활을 빠르게 사용하여 빗질하듯 가볍게 훑고(Brushing), 목적지인 선율 현에 도달했을 때 비로소 활의 무게를 온전히 안착시킬 것을 다짐합니다.\n억지 힘으로 세 현을 짓눌러 부수려 하지 않고, 밑선에서 윗선으로 부드러운 U자형(또는 원형) 스윙 궤적을 그리며 유려하게 미끄러질 것을 상상합니다.\n활을 잡은 손목과 손가락 관절이 뻣뻣해지지 않도록 텐션을 0으로 리셋하여, 화음이 부드럽고 매끄럽게 넘어가도록 우아하게 세팅합니다.\n화음을 굴려 연주한 후 탑 노트에 머물며, 소리가 홀 끝까지 퍼져나가는 파이프 오르간 같은 긴 여운과 공명을 내면의 귀로 먼저 듣습니다.",
