    "name": "왼손 트리플 스탑 프레임과 사전 튜닝 (Left-Hand Triple Stop Frame & Pre-Tuning)",
    "corePrinciple": "세 개의 음을 개별적으로 허둥지둥 짚는 것이 아니라, 허공에서 미리 하나의 통합된 화음 형태(Shape)를 구축하여 현에 동시에 낙하시키고, 순정률 기반의 화성적 튜닝을 통해 맥놀이 없는 완벽한 공명을 만들어내는 왼손 구조화 기술.",
    "before": "수직적으로 쌓인 세 개의 음표를 낱개의 점들이 아니라, 왼손 전체가 만들어내는 하나의 덩어리진 조각 작품(Shape)으로 시각화합니다.\n지판에 손을 대기 전, 허공에서 이미 세 손가락의 정확한 간격과 각도가 완벽하게 세팅되어 있을 것을 머릿속으로 치밀하게 계획합니다.\n1번과 4번 손가락 등 뼈대가 되는 외곽 프레임을 먼저 단단히 인지하고, 중간 손가락이 그 안에 자연스럽게 배치되도록 손의 균형을 세팅합니다.\n손가락을 벌리거나 오므리기 위해 들어간 수평적 텐션이 지판을 바닥까지 꽉 짓누르는 무식한 수직 압력(Squeezing)으로 변질되지 않도록 릴랙스합니다.\n세 음이 완벽한 협화음을 이룰 때 발생하는 눈부신 공명과, 악기 전체가 울리는 타르티니 톤(결합음)을 내면의 귀로 팽팽하게 미리 듣습니다.\n세 현을 동시에 짚더라도 넥을 받치는 엄지손가락에 과부하가 걸리지 않게, 손바닥 안쪽 근육을 스펀지처럼 부드럽게 이완할 것을 다짐합니다.",
    "during": [
      "[모양 확인] 세 손가락이 하나씩 차례로 무겁게 떨어지지 않고, 피아노 화음을 짚듯 허공에서 완벽한 모양을 갖춰 동시에 지판으로 착지하는가?",
      "[모양 확인] 손가락 끝이 다른 현을 간섭하지 않도록 관절이 적절히 세워져 있으면서도, 짚어야 할 현의 접촉면은 견고하게 확보하고 있는가?",
      "[모양 확인] 세 현을 동시에 짚고 있음에도 왼손 엄지가 넥을 강하게 쥐어짜거나 손목이 뻣뻣하게 굳어있지 않고 중립적이고 편안한 자세를 유지하는가?",
      "[느낌 확인] 세 손가락을 벌리기 위한 근육의 장력이 지판을 바닥까지 억지로 내리누르는 억센 수직 압력으로 둔갑하여 손을 경직시키지 않는가?",
      "[느낌 확인] 손가락이 단단한 나무 지판이 아닌, 현 자체의 탄력 있고 푹신한 텐션 위에 부드럽게 매달려(Hanging) 있는 가벼운 느낌이 드는가?",
      "[느낌 확인] 튜닝이 완벽하게 맞았을 때, 현의 진폭이 극대화되어 악기의 울림이 연주자의 쇄골과 턱까지 기분 좋게 파고드는 공명감이 있는가?",
      "[소리 확인] 활로 세 현을 그었을 때, 서로 음정이 어긋나서 발생하는 귀에 거슬리는 맥놀이(울렁거림) 없이 하나의 깨끗한 유리알처럼 맑은 소리가 나는가?",
      "[소리 확인] 의도하지 않은 옆 현을 손가락 살집으로 건드려서 나는 거칠고 탁한 방해음 없이, 오직 타겟으로 한 세 현의 소리만 투명하게 울리는가?",
      "[소리 확인] 멜로디 라인이 되는 음이 화성적으로 정확히 튜닝되어 전체 화음의 색채와 방향성을 묻히지 않고 명확하게 이끌어주는가?"
    ],
